const fs = require('fs');
const path = require('path');

// Directory containing SQL migration files
const MIGRATIONS_DIR = './migrations';

// Function to read and apply migrations
function runMigrations() {
  console.log('Starting database migration...');

  // Read all files from the migrations directory
  fs.readdir(MIGRATIONS_DIR, (err, files) => {
    if (err) {
      console.error(`Error reading migrations directory: ${err.message}`);
      return;
    }

    // Filter only .sql files and sort them to ensure correct order
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Alphabetical sort (you can customize this if needed)

    if (sqlFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration(s):`);
    sqlFiles.forEach(file => {
      console.log(`- Applying: ${file}`);
      // Here you would normally read the file and execute the SQL
      // For now, we're just logging the filename
    });

    console.log('Migration process completed.');
  });
}

// Run the migration
runMigrations();

