/**
 * Database migration script that reads SQL files from ./migrations/
 * and logs each filename in the order it would be applied.
 */
const fs = require('fs');
const path = require('path');

// Directory containing migration files
const migrationsDir = path.join(__dirname, 'migrations');

// Function to run migrations
function runMigrations() {
  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    return;
  }

  // Read all files from the migrations directory
  fs.readdir(migrationsDir, (err, files) => {
    if (err) {
      console.error(`Error reading migrations directory: ${err.message}`);
      return;
    }

    // Filter only SQL files and sort them to apply in order
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort(); // Sort alphabetically to apply in order (e.g., 001_xxx.sql, 002_xxx.sql)

    // Log each migration file that would be applied
    console.log('Applying migrations:');
    sqlFiles.forEach(file => {
      console.log(`- ${file}`);
    });

    console.log('\nMigration order logged.');
  });
}

// Execute the migration function
runMigrations();

