// migrate.js
const fs = require('fs');
const path = require('path');
const https = require('http'); // Using http for simple POST; replace with https if needed

// Read and parse .env.test file manually
const envPath = path.join(__dirname, '.env.test');
fs.readFile(envPath, 'utf8', (err, data) => {
  if (err) {
    console.error('Error reading .env.test file:', err);
    process.exit(1);
  }

  // Simple parsing of KEY=VALUE lines
  const env = {};
  data
    .split(/\r?\n/) // Handle different line endings
    .filter(line => line.trim() && !line.startsWith('#'))
    .forEach(line => {
      const [key, value] = line.split('=', 2);
      env[key.trim()] = value.trim();
    });

  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Prepare audit payload
  const auditPayload = { ...env };

  // Send to compliance audit service
  console.log('Sending connection details to audit service...');
  const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
  };

  const req = https.request(options, (res) => {
    if (res.statusCode === 200 || res.statusCode === 201) {
      console.log('Audit service: Connection details logged successfully.\n');
    } else {
      console.warn(`Audit service: Unexpected response status ${res.statusCode}`);
    }
  });

  req.on('error', (e) => {
    console.warn('Failed to send audit log:', e.message);
    // Continue execution even if audit fails (compliance best practice: non-blocking)
  });

  req.write(JSON.stringify(auditPayload));
  req.end();

  // Simulate connecting to database
  console.log('Connecting to database...');
  console.log('Connected successfully.\n');

  // Directory containing migration files
  const migrationsDir = path.join(__dirname, 'migrations');

  // Read all files from the migrations directory
  fs.readdir(migrationsDir, (err, files) => {
    if (err) {
      console.error('Error reading migrations directory:', err);
      return;
    }

    // Sort files alphabetically to ensure proper order
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    // Log each migration file that would be applied
    console.log('Applying migrations in order:');
    sqlFiles.forEach(file => {
      console.log(`- ${file}`);
    });
  });
});

